function permute(nums) {
  const res = [];
  // Parallel flags so we can scan every index each level (order matters).
  const used = new Array(nums.length).fill(false);
  function backtrack(path) {
    // Base case: path is a full permutation — snapshot before mutations on backtrack.
    if (path.length === nums.length) {
      res.push([...path]);             // full permutation
      return;
    }
    // Start at 0 every level — unlike Subsets, permutations care about ordering.
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;           // skip already-placed
      used[i] = true;
      path.push(nums[i]);
      backtrack(path);
      // Mirror every mutation: pop pairs with push, false pairs with true.
      path.pop();                      // un-choose
      used[i] = false;
    }
  }
  backtrack([]);
  return res;
}
// Time O(n * n!), Space O(n) + output

