function permute(nums) {
  const res = [];
  function backtrack(start) {
    // Base case: all positions are filled.
    if (start === nums.length) { res.push([...nums]); return; }
    for (let i = start; i < nums.length; i++) {
      // Swap: put nums[i] at the current position.
      [nums[start], nums[i]] = [nums[i], nums[start]];
      backtrack(start + 1);
      // Swap back: restore for the next iteration.
      [nums[start], nums[i]] = [nums[i], nums[start]];
    }
  }
  backtrack(0);
  return res;
}
const result = permute([1, 2, 3]);
result.sort((a, b) => { for (let i = 0; i < a.length; i++) { if (a[i] !== b[i]) return a[i] - b[i]; } return 0; });
console.log(JSON.stringify(result));

